import CommentRow from "./CommentRow";
import useComments from "./useComments";

function CommentFeed({ slug }) {
  const { comments, error } = useComments(slug);

  if (error) return <p className="error">{error}</p>;
  if (comments.length === 0) return null;

  return (
    <div className="feed">
      {comments.map((comment) => (
        <CommentRow key={comment.id} {...comment} />
      ))}
    </div>
  );
}

export default CommentFeed;

function articleCommentsUrl(slug) {
  return `/api/articles/${encodeURIComponent(slug)}/comments`;
}

async function requestJson(url, failureMessage) {
  const res = await fetch(url);

  if (!res.ok) {
    throw new Error(`${failureMessage}: ${res.status}`);
  }

  return res.json();
}

export async function getComments(slug) {
  const data = await requestJson(
    articleCommentsUrl(slug),
    "Failed to load comments",
  );

  return data.comments;
}

import { useEffect, useState } from "react";
import { getComments } from "./api";

const initialCommentState = {
  comments: [],
  error: null,
};

function useComments(slug) {
  const [state, setState] = useState(initialCommentState);

  useEffect(() => {
    let isActive = true;

    setState(initialCommentState);

    getComments(slug)
      .then((comments) => {
        if (isActive) {
          setState({ comments, error: null });
        }
      })
      .catch((err) => {
        if (isActive) {
          setState({ comments: [], error: err.message });
        }
      });

    return () => {
      isActive = false;
    };
  }, [slug]);

  return state;
}

export default useComments;

import CommentRow from "./CommentRow";

function CommentList({ comments }) {
  return (
    <div className="feed">
      {comments.map((comment) => (
        <CommentRow key={comment.id} {...comment} />
      ))}
    </div>
  );
}

export default CommentList;

